head.script:
			var headInfoArrLen = 0;  // 동적으로 생성된 헤더의 개수
			
           /**************************************************************************
            * function    : init
            * Description : 서브 메인 화면 초기화
            * Parameter   : 
            * Return      : 
            **************************************************************************/
	        function init() {
				this.document.title=divisionNm;
				resizeIframe();
					
				getMaxDate();
				searchData();
				
			}

			/**************************************************************************
             * function    : getMaxDate
             * Description : 데이터가 존재하는 마지막일 조회
             * Parameter   : null
             * Return      : null
             **************************************************************************/
        	function getMaxDate() {
        		var BISComDspDatDTO = {"BISComDspDatDTO":{}};
		       	callProFrame("BIS-KOFIABOND", "BISSrtPrcEstMtrxWhtSrchSO","searchData", BISComDspDatDTO,"BISComDspDatDTO","resp1");
        	}
        	
            /**************************************************************************
             * function    : searchData
             * Description : 데이터 조회
             * Parameter   : null
             * Return      : null
             **************************************************************************/
        	function searchData() {
				if( isValidDate(startDtDD.getValue()) == false ){
	             	showMsg("C_I029");
	             	return;
	          	}
        		
        		setGrdHeader();
        		reMakeGrid("", "");
        		
				WebSquare.ModelUtil.removeChildNodes( "BISSrtPrcEstMtrxWhtAvgDTO" );
				setValue("BISSrtPrcEstMtrxWhtAvgDTO/standardDt", startDtDD.getValue());
				setValue("BISSrtPrcEstMtrxWhtAvgDTO/applyGbCd", "C00");
				
				if(checkbox1.getValue()=="1") setValue("BISSrtPrcEstMtrxWhtAvgDTO/val20", "1");
				if(checkbox2.getValue()=="1") setValue("BISSrtPrcEstMtrxWhtAvgDTO/val21", "1");
				if(checkbox3.getValue()=="1") setValue("BISSrtPrcEstMtrxWhtAvgDTO/val22", "1");
				
		       	var BISSrtPrcEstMtrxWhtAvgDTO = WebSquare.xml.serialize(getInstanceNode("BISSrtPrcEstMtrxWhtAvgDTO"));
				callProFrameProcess("BIS-KOFIABOND","BISSrtPrcEstMtrxWhtAvgSrchSO","selectList",BISSrtPrcEstMtrxWhtAvgDTO,"resp",true);
        	}
        				
        	function setGrdHeader(){
        		setValue("BISBndSrtPrcDayDTO/standardDt", startDtDD.getValue());
        		setValue("BISBndSrtPrcDayDTO/applyGbCd", "C00");
        		
        		var BISBndSrtPrcDayDTO = {"BISBndSrtPrcDayDTO":{}};
		        callProFrame("BIS-KOFIABOND","BISBndSrtPrcSrchSO","getHeadList",BISBndSrtPrcDayDTO, "BISBndSrtPrcDayDTO","respHead");
        	}
        	
            
       /**************************************************************************
        * function    : remakeGrid
        * Description : 그리드 헤더정보 재정의(최종호가 종목정보 세팅)
        * Parameter   : sProgNm(프로그램명), sGridHeight(그리드 height)
        * Return      : 그리드 헤더정보
        **************************************************************************/
        function reMakeGrid(sProgNm, sGridHeight) {
	    	grdMain.hide();
	              
	        if (sGridHeight == "" || sGridHeight == null) sGridHeight = "580";
	        
	        var i, j;
	        var grid = '';
	        var event = '';
	        var alignCd = "center";       
			var wordWrap = "white-space:nowrap;text-overflow:ellipsis;word-wrap:break-word;"; 
			//var wordWrap = "word-break:keep-all;";
			// word_wrap  : normal, break-word
			// word-break : break-all(단어상관없이자르기), keep-all(단어에 맞게자르기) 
            // colMerge="true" upperColumn="largeCategoryMrk"
            
            //white-space:nowrap; // 그냥 두어도 무방하나 normal로 overwrite하는 것이 옳음
			    //text-overflow:ellipsis; // 삭제
			    //word-wrap:break-word; /
			    
	        headInfoArr = WebSquare.ModelUtil.findInstanceNodes( "respHead/root/message/BISBndSrtPrcDayListDTO/BISBndSrtPrcDayDTO" );
	        headInfoArrLen = headInfoArr.length;
	        var autoFitWidth = 320 + (headInfoArr.legnht * 70); 
	        //var autoFitWidth = 600;
			
	        grid += "<w2:grid xmlns='http://www.w3.org/1999/xhtml' xmlns:w2='http://www.inswave.com/websquare' xmlns:ev='http://www.w3.org/2001/xml-events'\n";
	        grid += "    style='height:" + sGridHeight + "px;'\n";
	        grid += "    rowNumStyle='' summary = '" + sProgNm + "' readOnlyTabIgnore='true' \n";  
	        grid += "    tooltipStyle='vertical-align:middle;" + wordWrap + "' overflowY='auto' overflowX='auto' \n";
	        grid += "    id='grdMain' baseNode='BISSrtPrcEstMtrxWhtAvgListDTO'";  
	        grid += "    class='gridtable9 mt3 fl ' focusMode='both' selectedRowColor='transparent' selectedCellColor='transparent' repeatNode='BISSrtPrcEstMtrxWhtAvgDTO'";
	        grid += "    sortable='' autoFit='allColumn' autoFitMinWidth='"+ autoFitWidth +"'";
            grid += "    oddEvenColorDisplay='false' oddRowBackgroundColor='#FFFFFF' evenRowBackgroundColor='#F5F5F5' rowMouseOver='true' rowMouseOverColor='#cce2ff' visibleRowNum='all'>\n";
            
            grid += " <caption>" + sProgNm + "</caption>";
            
            grid += "    <w2:header height='20px' style='padding-top:2px;' columnStyle='' id='header2' class='' columnClass=''>\n";
            
           	grid += "        <w2:row id='row" + i + "' style=''>\n";
        	grid += "			<w2:column id='head_1' height='20px' width='80'  inputType='text' value='종류' ></w2:column>			\n";
			grid += "			<w2:column id='head_2' height='20px' width='100' inputType='text' value='종류명'></w2:column>		\n";
			grid += "			<w2:column id='head_3' height='20px' width='100' inputType='text' value='신용등급' ></w2:column>		\n";
			grid += "			<w2:column id='head_4' height='20px' width='80' inputType='text' value='구분'  ></w2:column>			\n";
 			       
            for( i=0 ; i<headInfoArr.length ; i++ ){
            	grid += "  		<w2:column inputType='text' valueType='binary' width='50' height='20px' style='padding-top:2px' id='h_" + i + "'></w2:column> \n";
	        }
	        grid += "			<w2:column id='head_5' height='20px' width='100' inputType='text' value='시가코드' hidden='true'></w2:column>			\n";
            
            if (headInfoArr.length > 0) grid += "        </w2:row>\n";            
            	grid += "    </w2:header>\n";
                        
	        /* grid body 시작 */
            //grid += "    <w2:gBody style='height:20px;padding-top:2px;' columnStyle='' id='gBody2' columnClass='brgrid'>\n";
            grid += "    <w2:gBody style='height:20px;padding-top:2px;' columnStyle='' id='gBody2'>\n";
            grid += "        <w2:row id='gRow1' style=''>\n";  
			grid += "        <w2:column id='largeCategoryMrk' style='height:20px' width='50' inputType='text' readOnly='true' colMerge='true'></w2:column>		\n";
			grid += "        <w2:column id='typeNmMrk'        style='height:20px' width='90' inputType='text' readOnly='true' colMerge='true' upperColumn='largeCategoryMrk'></w2:column>		\n";
			grid += "        <w2:column id='creditRnkMrk'     style='height:20px' width='90' inputType='text' readOnly='true' colMerge='true'></w2:column>		\n";
			grid += "        <w2:column id='val99'            style='height:20px' width='90' inputType='text' readOnly='true'></w2:column>		\n";
			
            for( i=0 ; i<headInfoArr.length ; i++ ){
               var bodyId = "val"+(i+1);
               grid += "     <w2:column valueType='binary' inputType = 'text' style='height:20px;padding-top:2px' textAlign='center' width='80' id='" + bodyId + "' readOnly='true' >	\n";
               grid += "     </w2:column>\n";       
            }
            
            grid += "        <w2:column id='sigaBrnCd' hidden='true' inputType='text'></w2:column>														\n";
            
            grid += "        </w2:row>\n";
            grid += "    </w2:gBody>\n";  
            grid += "</w2:grid>\n";

            grdMain.setGridStyle(WebSquare.xml.parse(grid, true));

            for( var i=0 ; i<headInfoArr.length ; i++ ){
                grdMain.setHeaderValue( "h_" + i, WebSquare.xml.getValue( headInfoArr[i] , "remainTrmCtgy" ) );
            }
              		        
            //grdMain.setFixedColumn(4);
            grdMain.show();
                            
          }
                  				
        	/**************************************************************************
             * function    : callBack
             * Description : submission 실행 후 Callback
             * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
             * Return      : null
             **************************************************************************/
        	function callBack(svcId, fnId, strResp){
        		var value, innerText;
        		   
        		if (svcId == "BISSrtPrcEstMtrxWhtAvgSrchSO"){
					if (fnId == "selectList"){
						grdMain.setXML( getInstanceNode("resp/root/message/BISSrtPrcEstMtrxWhtAvgListDTO") );
						resizeIframe();
						
						for(i=0 ; i<grdMain.getRowCount() ; i++){
							for(j=4 ; j<headInfoArrLen+4 ; j++){
								value = grdMain.getCellData( i, j );
								
								if( WebSquare.util.parseFloat(value) == 0 || value == "" ){
									grdMain.setCellData( i, j, "-" );
								}	
								 
								/*
								if(grdMain.getCellData( i, 3 ) == "수익률" && grdMain.getCellData( i, j ) != "-" ){
									innerText = "<a href=javascript:openPopIssueCompNmInfo("+ grdMain.getCellData( i, "sigaBrnCd" ) + "," + j +")>" + grdMain.getCellData( i, j ) + "</a>";
									grdMain.setCellData( i, j, innerText);
								}
								*/
							}
						}
	 				}
	 			}else if(svcId == "BISSrtPrcEstMtrxWhtSrchSO"){
					if(fnId == "searchData"){
						startDtDD.setValue( getValue("resp1/root/message/BISComDspDatListDTO/BISComDspDatDTO/val1") );
					} 
				}
            }

			function openPopIssueCompNmInfo(sigaBrnCd, j){
				remainTrm = getValue("respHead/root/message/BISBndSrtPrcDayListDTO/BISBndSrtPrcDayDTO[" + ( j-3 ) + "]/attrCd");
				
				openPopup2("popCallBackIssueCompNmInfo",  "/xml/Com/pop/BISSrtPrcEstPop.xml",
						{ width      : 1320
						, height     : 570  
						, resizable  : false
						, scrollbars : false 
						, popId : "BISSrtPrcEstPop"
						},
						 {
		                 	  "standardDt" : startDtDD.getValue()
		                 	, "sigaBrnCd"    : sigaBrnCd
		                 	, "remainTrmYM"  : remainTrm
		                 }
				);
			}

			/**************************************************************************
			* function    : openPopItemcdInfo
			* Description : 종목명/KR코드 검색 팝업 Open
			* Parameter   : null
			* Return      : null
			**************************************************************************/
			function popCallBackIssueCompNmInfo(retXml, popId){
				WebSquare.ModelUtil.setInstanceNode( retXml, "respIssCompNmInfo", null, "replace" );
				WebSquare.util.closePopup(popId);
				
				issCompNm.setValue( getValue("respIssCompNmInfo/BISIssCompPopDTO/issueManNm") );
			}   
						            
            /**************************************************************************
             * function    : excelDownLoad
             * Description : 그리드의 내용을 엑셀로 다운로드
             * Parameter   : null
             * Return      : null
             **************************************************************************/
            function excelDownLoad(removeCol) {
           		saveExcelDown(grdMain, divisionNm, "1", true, false, removeCol);
            }
            /*
            function excelDownLoad(removeCol) {
            	grdMain.setXML( getInstanceNode("resp/root/message/BISSrtPrcEstMtrxWhtAvgListDTO") );
            	for(i=0;i<grdMain.getRowCount();i++){
					for(j=4;j<18;j++){
						num = grdMain.getCellData( i , j );
						if(num=="0"||num=="0.00"||num==""){
							grdMain.setCellData( i , j , "-" );
						}
					}
				}
            	saveExcelDown(grdMain, divisionNm, "1", true, false, removeCol);
            	//searchData();
            }			
				*/
